/**
 * Integration e2e: real backend + pipeline + SYNTHETIC sample data.
 *
 *   npm run e2e        (starts uvicorn on :8000 and `vite preview` on :4173; see playwright.config.ts)
 *
 * Needs: backend/app/main.py, the pipeline, and sample_data/synthetic/high/ (generated by the
 * pipeline's synthetic module). Upload → analysis → results → clinician PDF.
 */
import { expect, test } from '@playwright/test';
import { existsSync, readdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const SAMPLE_DIR = path.resolve(here, '../../sample_data/synthetic/high');

/** Exact file name first (as documented), then a tolerant search in the same folder. */
function sample(exact: string, pattern: RegExp): string | undefined {
  const p = path.join(SAMPLE_DIR, exact);
  if (existsSync(p)) return p;
  if (!existsSync(SAMPLE_DIR)) return undefined;
  const hit = readdirSync(SAMPLE_DIR).find((n) => pattern.test(n));
  return hit ? path.join(SAMPLE_DIR, hit) : undefined;
}

test('upload synthetic HIGH captures → risk level → clinician PDF', async ({ page }) => {
  const wl = sample(
    'SYNTHETIC_lateral_tongue_right_wl.jpg',
    /lateral_tongue_right_wl\.(jpe?g|png)$/i,
  );
  const af = sample(
    'SYNTHETIC_lateral_tongue_right_af.jpg',
    /lateral_tongue_right_af\.(jpe?g|png)$/i,
  );
  const refWl = sample(
    'SYNTHETIC_lateral_tongue_left_wl.jpg',
    /lateral_tongue_left_wl\.(jpe?g|png)$/i,
  );
  const refAf = sample(
    'SYNTHETIC_lateral_tongue_left_af.jpg',
    /lateral_tongue_left_af\.(jpe?g|png)$/i,
  );
  const spectrum = sample('spectrum.csv', /spectr.*\.(csv|json)$/i);
  expect(wl, `white-light sample missing in ${SAMPLE_DIR}`).toBeTruthy();
  expect(af, `autofluorescence sample missing in ${SAMPLE_DIR}`).toBeTruthy();

  // 1. Open the app and go to Upload.
  await page.goto('/');
  await expect(page.getByTestId('prototype-banner')).toHaveText(
    'Research prototype — not for clinical use',
  );
  await page.getByRole('link', { name: 'New screening' }).first().click();
  await expect(page).toHaveURL(/\/upload$/);

  // 2. Choose the site on the map; the contralateral site is suggested as the reference.
  await page.getByRole('button', { name: /^Right lateral tongue/ }).click();
  await expect(page.getByText(/Reference site suggested: Left lateral tongue/)).toBeVisible();

  // 3. Captures.
  await page.getByTestId('file-wl').setInputFiles(wl!);
  await page.getByTestId('file-af').setInputFiles(af!);
  if (refWl && refAf) {
    await page.getByTestId('file-refWl').setInputFiles(refWl);
    await page.getByTestId('file-refAf').setInputFiles(refAf);
  }
  if (spectrum) await page.getByTestId('file-spectrum').setInputFiles(spectrum);
  await expect(page.getByLabel('Data source')).toHaveValue('synthetic');

  // 4. Consent (required) and submit.
  await page.getByText(/The person was told what this screening involves/).click();
  await expect(page.getByTestId('consent')).toBeChecked();
  await page.getByTestId('submit-upload').click();
  await expect(page.getByTestId('analysis-overlay')).toBeVisible();

  // 5. Results.
  const badge = page.getByTestId('risk-badge');
  await expect(badge).toBeVisible({ timeout: 180_000 });
  const level = await badge.getAttribute('data-level');
  expect(['LOW', 'MODERATE', 'HIGH', 'INCONCLUSIVE']).toContain(level);
  test.info().annotations.push({ type: 'risk level', description: String(level) });
  await expect(page.getByTestId('review-chip')).toHaveText('Pending clinician review');
  await expect(page.getByTestId('synthetic-ribbon')).toBeVisible();
  await expect(page.getByTestId('disclaimer')).toContainText('not a diagnosis');
  await expect(page.getByTestId('prototype-banner')).toBeVisible();

  // 6. Clinician PDF.
  const href = await page.getByTestId('report-link').getAttribute('href');
  expect(href).toMatch(/\/api\/v1\/screenings\/.+\/report\.pdf/);
  const res = await page.request.get(new URL(href!, page.url()).toString(), { timeout: 120_000 });
  expect(res.status()).toBe(200);
  expect(res.headers()['content-type']).toContain('application/pdf');
  const body = await res.body();
  expect(body.subarray(0, 4).toString()).toBe('%PDF');
  expect(body.length).toBeGreaterThan(20 * 1024);
});
